var i=`0476-fattoush`;var n=`world-0476`;var s=`LB`;var o=`western-asia`;var a=4;var r=22;var u={en:`Fattoush`,ua:`Фатуш`};var g={en:`A traditional dish from Lebanon, centered on tomato, cucumber, radish, lettuce. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: помідор, огірок, редиска, салат латук. Домашній варіант із кількостями продуктів за етапами приготування.`};var c=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:12,i:[[`tomato`,300,`g`],[`cucumber`,230,`g`],[`radish`,120,`g`],[`lettuce`,200,`g`],[`parsley`,35,`g`],[`mint`,20,`g`]]},{en:`Toast these ingredients over medium heat for about 5 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 5 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:5,i:[[`pita-bread`,2,`pcs`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:5,i:[[`extra-virgin-olive-oil`,55,`ml`],[`lemon-juice`,60,`ml`],[`sumac`,6,`g`],[`pomegranate-molasses`,25,`ml`]]}];var d={slug:i,id:n,country:`LB`,region:o,servings:4,minutes:22,title:u,text:g,steps:c};export{s as country,d as default,n as id,r as minutes,o as region,a as servings,i as slug,c as steps,g as text,u as title};